/* cards */
function setCard(c,on){c.classList.toggle("flip",on);c.querySelector(".def").hidden=!on;c.querySelector(".tap").hidden=on;c.setAttribute("aria-pressed",String(on));}
function makeCards(data, boxId, btnId, prefix){
  const box=document.getElementById(boxId); if(!box) return;
  data.forEach(([t,def],i)=>{
    const c=document.createElement("button");
    c.type="button"; c.className="card"; c.id=prefix+i; c.setAttribute("aria-pressed","false");
    c.innerHTML='<span class="term"></span><span class="tap">Tap to see meaning</span><span class="def" hidden></span>';
    c.querySelector(".term").textContent=t; c.querySelector(".def").textContent=def;
    c.addEventListener("click",()=>setCard(c,!c.classList.contains("flip")));
    box.appendChild(c);
  });
  const btn=document.getElementById(btnId);
  btn.addEventListener("click",()=>{
    const show=btn.textContent.startsWith("Show");
    box.querySelectorAll(".card").forEach(c=>setCard(c,show));
    btn.textContent=show?"Hide all meanings":"Show all meanings";
  });
}
