/* quiz */
function makeQuiz(data, listId, scoreId, resetId, prefix){
  const list=document.getElementById(listId), scoreEl=document.getElementById(scoreId); if(!list) return;
  let answered=0, correct=0;
  const update=()=>{scoreEl.textContent=answered+" of "+data.length+" answered · "+correct+" correct";};
  function build(){
    list.innerHTML=""; answered=0; correct=0; update();
    data.forEach((item,qi)=>{
      const box=document.createElement("div"); box.className="q";
      box.innerHTML='<span class="qn">Question '+(qi+1)+' of '+data.length+'</span><p class="prompt"></p><div class="opts"></div><p class="why" hidden></p>';
      box.querySelector(".prompt").textContent=item.q;
      const opts=box.querySelector(".opts"), why=box.querySelector(".why");
      item.o.forEach((text,oi)=>{
        const b=document.createElement("button"); b.type="button"; b.className="opt"; b.id=prefix+qi+"o"+oi; b.textContent=text;
        b.addEventListener("click",()=>{
          if(box.dataset.done) return; box.dataset.done="1"; answered++;
          const ok=oi===item.a; if(ok) correct++;
          opts.querySelectorAll(".opt").forEach((x,xi)=>{x.disabled=true; if(xi===item.a) x.classList.add("right");});
          if(!ok) b.classList.add("wrong");
          why.innerHTML=ok?'<b class="ok">Correct.</b> ':'<b class="no">Not quite.</b> ';
          why.appendChild(document.createTextNode(item.w)); why.hidden=false; update();
        });
        opts.appendChild(b);
      });
      list.appendChild(box);
    });
  }
  document.getElementById(resetId).addEventListener("click",build);
  build();
}
